import{_ as e,o,c as a,a2 as n}from"./chunks/framework.CZo9GF0W.js";const p=JSON.parse('{"title":"Through an SSH bastion","description":"","frontmatter":{},"headers":[],"relativePath":"recipes/ssh.md","filePath":"recipes/ssh.md","lastUpdated":1789060268000}'),s={name:"recipes/ssh.md"};function r(i,t,h,d,l,c){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="through-an-ssh-bastion" tabindex="-1">Through an SSH bastion <a class="header-anchor" href="#through-an-ssh-bastion" aria-label="Permalink to &quot;Through an SSH bastion&quot;">​</a></h1><p>Pitta opens the tunnel itself. You do not need a separate <code>ssh -L</code> running, and you should not point the profile at a port you forwarded by hand — Pitta&#39;s tunnel is lifecycle-managed with the connection and closes with it.</p><h2 id="before-you-reach-for-it" tabindex="-1">Before you reach for it <a class="header-anchor" href="#before-you-reach-for-it" aria-label="Permalink to &quot;Before you reach for it&quot;">​</a></h2><p>If VS Code is <strong>already attached to the bastion</strong> over Remote-SSH, you do not need a tunnel. Pitta is running on the bastion, so the database&#39;s private hostname resolves directly. Adding a tunnel there would open a second SSH connection from the bastion to somewhere else.</p><p>The tunnel is for the case where the machine VS Code is on can reach the <em>bastion</em> but not the database.</p><h2 id="the-fields" tabindex="-1">The fields <a class="header-anchor" href="#the-fields" aria-label="Permalink to &quot;The fields&quot;">​</a></h2><p>Nine of them, identical for every engine, because they describe the bastion rather than the database.</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Use SSH tunnel</td><td>on</td></tr><tr><td>SSH host</td><td><code>bastion.example.com</code></td></tr><tr><td>SSH port</td><td><code>22</code></td></tr><tr><td>SSH user</td><td><code>ubuntu</code></td></tr><tr><td>SSH auth</td><td><code>ssh-agent</code>, <code>Private key</code>, or <code>Password</code></td></tr><tr><td>Private key</td><td>path, for the key option</td></tr><tr><td>Key passphrase</td><td>goes to the keychain</td></tr></tbody></table><p>And the database fields are then filled in <strong>as the bastion sees them</strong>:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Host</td><td><code>orders.internal</code> — resolved on the bastion</td></tr><tr><td>Port</td><td><code>5432</code> — the database&#39;s real port</td></tr></tbody></table><p>Not <code>localhost</code>, and not a local forwarded port. Pitta forwards to <code>host:port</code> from the bastion&#39;s side.</p><h2 id="host-keys" tabindex="-1">Host keys <a class="header-anchor" href="#host-keys" aria-label="Permalink to &quot;Host keys&quot;">​</a></h2><p>The bastion&#39;s key is verified against <code>~/.ssh/known_hosts</code> <strong>on the machine Pitta is running on</strong>. An unknown key prompts with its fingerprint and waits. It is never auto-accepted, and a key that does not match a known one stops the connection rather than warning about it.</p><p>From a fresh remote or a rebuilt container this means a prompt for a key your laptop has known for years. That is correct: it is a different machine&#39;s trust store.</p><h2 id="ssh-agent" tabindex="-1">ssh-agent <a class="header-anchor" href="#ssh-agent" aria-label="Permalink to &quot;ssh-agent&quot;">​</a></h2><p>The agent option needs <code>SSH_AUTH_SOCK</code> set in the <strong>extension host&#39;s</strong> environment. Locally that is usually inherited. Inside a container it usually is not, unless you forwarded the agent in.</p><p>Remote-SSH forwards your agent to the remote if <code>ForwardAgent yes</code> is set for that host, which makes the agent option work from a remote window too.</p><h2 id="jump-hosts" tabindex="-1">Jump hosts <a class="header-anchor" href="#jump-hosts" aria-label="Permalink to &quot;Jump hosts&quot;">​</a></h2><p>A jump host is supported: the tunnel is established through it to the bastion, and from there to the database. Configure it on the profile rather than in <code>~/.ssh/config</code> — Pitta uses its own SSH implementation and does not read the <code>ProxyJump</code> directives in that file.</p><h2 id="topologies-that-refuse-a-tunnel" tabindex="-1">Topologies that refuse a tunnel <a class="header-anchor" href="#topologies-that-refuse-a-tunnel" aria-label="Permalink to &quot;Topologies that refuse a tunnel&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">This is deliberate, not a limitation to work around</p><p>A tunnel is <strong>refused</strong>, with the reason, for:</p><ul><li><strong>Redis Cluster</strong> — the client is told about every node and connects to all of them.</li><li><strong>Redis Sentinel</strong> — the client is told the master&#39;s address by the sentinel and connects to it.</li><li><strong>MongoDB with an SRV URI or a seed list</strong> — the driver discovers the replica set members and connects to them.</li></ul><p>In each case the addresses the client is handed only resolve on the bastion&#39;s side of the tunnel. One forwarded port cannot serve them. Honouring the tunnel for the seed and then bypassing it for every node after that would look like it worked and would not be.</p><p>Use a VPN, a bastion-side proxy, or attach VS Code to a machine inside the network with Remote-SSH.</p></div><p>A <strong>standalone</strong> MongoDB and a <strong>standalone</strong> Redis both tunnel normally; it is the self-discovering topologies that cannot.</p><h2 id="things-that-look-like-bugs" tabindex="-1">Things that look like bugs <a class="header-anchor" href="#things-that-look-like-bugs" aria-label="Permalink to &quot;Things that look like bugs&quot;">​</a></h2><ul><li><strong><code>All configured authentication methods failed</code></strong> with the agent option: <code>SSH_AUTH_SOCK</code> is not visible to the extension host.</li><li><strong>Connects, then the database times out.</strong> The tunnel is up and the database host or port is wrong <em>as seen from the bastion</em>. Check it with <code>ssh bastion &#39;nc -z orders.internal 5432&#39;</code>.</li><li><strong>Works from the terminal, not from Pitta.</strong> Your terminal is reading <code>~/.ssh/config</code>; Pitta is not. Put the host, port, user and key on the profile explicitly.</li></ul>',24)])])}const f=e(s,[["render",r]]);export{p as __pageData,f as default};
